import{_ as r,o as n,c as s,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/gruppenprozesse-betrieb-adresse-zuweisen.png",b=JSON.parse('{"title":"Einen Betrieb oder eine Adresse gruppenweise zuweisen","description":"","frontmatter":{"title":"Einen Betrieb oder eine Adresse gruppenweise zuweisen","source_pageid":802,"source_revision":5340},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/betrieb-adresse-zuweisen-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/betrieb-adresse-zuweisen-gruppenprozesse-allgemein.md"}'),t={name:"schild3/suchen-gruppenprozesse/betrieb-adresse-zuweisen-gruppenprozesse-allgemein.md"};function p(u,e,d,l,o,g){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="einen-betrieb-oder-eine-adresse-gruppenweise-zuweisen" tabindex="-1">Einen Betrieb oder eine Adresse gruppenweise zuweisen <a class="header-anchor" href="#einen-betrieb-oder-eine-adresse-gruppenweise-zuweisen" aria-label="Permalink to &quot;Einen Betrieb oder eine Adresse gruppenweise zuweisen&quot;">​</a></h1><p>Ordnen Sie mehreren Schülerinnen und Schülern denselben Betrieb zu, etwa für Praktikum oder Ausbildung. Die Adresse wird aus den bereits verwalteten Einträgen ausgewählt.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-betrieb-adresse-zuweisen.png"><img src="'+a+'" alt="Eingabe der Daten, um einen Betrieb zuzuweisen." loading="lazy"></a></p><p><em>Eingabe der Daten, um einen Betrieb zuzuweisen.</em></p><p>Wenn mehrere Schülerinnen oder Schüler in einem Betrieb ihr Praktikum oder ihre Ausbildung absolvieren, kann die Zuweisung der Adresse des Betriebes auch über einen Gruppenprozess erfolgen.</p><p>Hierbei werden die erforderlichen Daten erfragt und anschließend den Schülern zugewiesen.</p><p>Klicken Sie auf <strong>Auswahl</strong>, um eine vorhandene Adresse zu wählen. Neue Adressen legen Sie unter <strong>Kataloge → Allgemeine Adressen</strong> an; siehe <a href="/schild3/unterricht-kataloge/allgemeine-adressen-allgemeine-kataloge.html">Allgemeine Adressen</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Betrieb/Adresse_zuweisen_(Gruppenprozesse_Allgemein)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5340.</p>',9)])])}const c=r(t,[["render",p]]);export{b as __pageData,c as default};
